def safe_join(values: Any, limit: int = 4) -> str:
    if isinstance(values, dict):
        values = list(values.keys())
    if isinstance(values, list):
        shown = [str(x) for x in values[:limit]]
        if len(values) > limit:
            shown.append(f'+{len(values) - limit}')
        return ', '.join(shown)
