def fmt_bytes(value: Any) -> str:
    try:
        size = float(value or 0)
    except Exception:
        return '0 B'
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    unit = 0
    while size >= 1024 and unit < len(units) - 1:
        size /= 1024
        unit += 1
    return f'{size:.1f} {units[unit]}' if unit else f'{int(size)} B'


